## Example 2: Matrix Multiplication (Tiled/Blocked Operation)

Matrix multiplication is more complex as it often requires tiling or blocking for efficiency, which RAJA handles through its loop structure and memory access patterns.

### 1. Original CUDA Code (Simplified)

We will use a simple, non-tiled implementation for direct comparison, though real-world CUDA code would be heavily optimized.

```c++
// cuda_matmul.cu
#include <cuda_runtime.h>
#include <iostream>

// Kernel for C = A * B (C[i][j] = sum(A[i][k] * B[k][j]))
__global__ void matmulKernel(const float* A, const float* B, float* C, int M, int N, int K) {
    int row = blockIdx.y * blockDim.y + threadIdx.y; // M dimension
    int col = blockIdx.x * blockDim.x + threadIdx.x; // N dimension

    if (row < M && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            // A is M x K, B is K x N
            sum += A[row * K + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}

// ... (Host code for allocation and launch omitted for brevity)
```

### 2. RAJA Portable Code

RAJA allows you to express the nested loops of matrix multiplication directly, and the backend handles the mapping to threads/blocks.

```c++
// raja_matmul.cpp
#include <iostream>
#include <vector>
#include <raja/raja.hpp>

using namespace raja;

void run_raja_matmul(const std::vector<float>& h_A, 
                     const std::vector<float>& h_B, 
                     std::vector<float>& h_C, 
                     int M, int N, int K) 
{
    // RAJA allows us to express the triple loop structure directly.
    // The parallel_for over the outer loop (M) is the primary parallelization point.

    parallel_for(
        default_policy, 
        range(0, M), // Loop over rows of C (M)
        [&](int i) { // i is the row index

            // Inside the row loop, we parallelize over columns (N)
            parallel_for(
                default_policy, 
                range(0, N), // Loop over columns of C (N)
                [&](int j) { // j is the column index

                    float sum = 0.0f;
                    // The inner loop (K) is sequential for this simple example
                    for (int k = 0; k < K; ++k) {
                        // Accessing data using standard C++ indexing
                        sum += h_A[i * K + k] * h_B[k * N + j];
                    }
                    // Writing the result back to the output matrix C
                    h_C[i * N + j] = sum;
                }
            );
        }
    );
}

int main() {
    // Define matrix dimensions
    const int M = 1024; // Rows of A, Rows of C
    const int N = 1024; // Cols of B, Cols of C
    const int K = 1024; // Inner dimension

    // Initialize matrices (using simple values for testing)
    std::vector<float> h_A(M * K, 1.0f / K); // A[i][k] = 1/K
    std::vector<float> h_B(K * N, 1.0f / K); // B[k][j] = 1/K
    std::vector<float> h_C(M * N, 0.0f);

    std::cout << "Running RAJA Matrix Multiplication (" << M << "x" << K << " * " << K << "x" << N << ")..." << std::endl;

    // The RAJA call handles the entire parallel execution pipeline
    run_raja_matmul(h_A, h_B, h_C, M, N, K);

    // Expected result for A[i][k] = 1/K and B[k][j] = 1/K is C[i][j] = 1.0
    std::cout << "Matrix multiplication complete. Result at C[0][0]: " << h_C[0] << std::endl;
    return 0;
}
