    std::vector<float> h_B(K * N, 1.0f / K);
    std::vector<float> h_C(M * N, 0.0f);

    std::cout << "Running RAJA Matrix Multiplication (" << M << "x" << K << " * " << K << "x" << N << ")..." << std::endl;

    // In a production RAJA code, the vectors would be RAJA::device_vector 
    // to ensure the data resides on the GPU throughout the computation.
    run_raja_matmul(h_A, h_B, h_C, M, N, K);

