// cuda_matmul.cu
#include <cuda_runtime.h>
#include <iostream>

// CUDA Kernel for C = A * B
__global__ void matmulKernel(const float* A, const float* B, float* C, int M, int N, int K) {
    // Calculate the global row (row_m) and column (col_n) for the output C[row_m][col_n]
    int row_m = blockIdx.y * blockDim.y + threadIdx.y;
    int col_n = blockIdx.x * blockDim.x + threadIdx.x;

    if (row_m < M && col_n < N) {
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            // C[row_m][col_n] += A[row_m][k] * B[k][col_n]
            sum += A[row_m * K + k] * B[k * N + col_n];
        }
        C[row_m * N + col_n] = sum;
    }
}

// ... (Host code for memory management and launch omitted for brevity)
```

### 2. RAJA Conversion

RAJA allows you to express the nested loops of matrix multiplication using nested `parallel_for` calls, letting the RAJA backend manage the thread mapping for each dimension.

```c++
// raja_matmul.cpp
#include <iostream>
#include <vector>
#include <raja/raja.hpp>

using namespace raja;

// Dimensions
const int M = 128; // Rows of A and C
const int N = 128; // Columns of B and C
const int K = 128; // Inner dimension

void run_raja_matmul(std::vector<float>& h_A, std::vector<float>& h_B, std::vector<float>& h_C) {

    // Initialize C to zero (necessary for accumulation)
    std::fill(h_C.begin(), h_C.end(), 0.0f);

    // RAJA handles the mapping of the outer loops (M and N) to the grid/blocks.
    // The inner loop (K) remains sequential within each thread.

    // Outer loop: Iterate over rows of C (M)
    parallel_for(0, M, [&](int row_m) {
        // Middle loop: Iterate over columns of C (N)
        parallel_for(0, N, [&](int col_n) {
            float sum = 0.0f;
            // Inner loop: The reduction/accumulation loop (K)
            for (int k = 0; k < K; ++k) {
                // Accessing data using 1D indexing, matching the CUDA layout
                sum += h_A[row_m * K + k] * h_B[k * N + col_n];
            }
            // Store the result
            h_C[row_m * N + col_n] = sum;
        });
    });
}

int main() {
