    std::vector<float> h_A(M * K);
    std::vector<float> h_B(K * N);
    std::vector<float> h_C(M * N);

    // Initialize data (e.g., to 1.0)
    std::fill(h_A.begin(), h_A.end(), 1.0f);
    std::fill(h_B.begin(), h_B.end(), 1.0f);

