## Example 2: Matrix Multiplication (Tiled/Blocked Operation)

Matrix multiplication is more complex because it requires managing 2D indexing and often benefits from tiling/blocking, which RAJA can help abstract.

### 1. Original CUDA Code (Simplified)

We will use a simple, non-tiled implementation for direct comparison.

```c++
// cuda_matmul.cu
#include <cuda_runtime.h>
#include <iostream>

// CUDA Kernel for C = A * B
__global__ void matmulKernel(const float* A, const float* B, float* C, int M, int N, int K) {
    // Calculate the global row and column indices for C
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < M && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            // A is M x K, B is K x N
            sum += A[row * K + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}

// ... (Host code for allocation and launch similar to Example 1)
```

### 2. RAJA Conversion

RAJA's `parallel_for` can handle multi-dimensional iteration by using nested ranges or by defining a single flattened range and calculating the 2D indices inside the body.

```c++
// raja_matmul.cpp
#include <iostream>
#include <vector>
#include <raja/raja.hpp>

using namespace raja;

void run_raja_matmul(const std::vector<float>& h_A, const std::vector<float>& h_B, std::vector<float>& h_C, 
                      int M, int N, int K) {

    auto policy = default_policy<cuda_backend>(); 

    // We iterate over the resulting matrix C (M rows, N columns)
    // We use a flattened range (0 to M*N - 1) and calculate 2D indices inside.
    parallel_for(policy, 
                  range(0, M * N), 
                  [&](int flat_idx) {

                      // Convert flat index back to 2D coordinates (row, col)
                      int row = flat_idx / N;
                      int col = flat_idx % N;

                      float sum = 0.0f;

                      // The inner loop (K dimension) remains sequential on the thread
                      for (int k = 0; k < K; ++k) {
                          // Accessing A (M x K) and B (K x N)
                          // Note: RAJA handles the memory mapping for these accesses.
                          sum += h_A[row * K + k] * h_B[k * N + col];
                      }

                      // Store result in C (M x N)
                      h_C[flat_idx] = sum;
                  });
}

int main() {
    // Define matrix dimensions
    const int M = 128; // Rows of A, Rows of C
    const int N = 128; // Cols of B, Cols of C
    const int K = 128; // Inner dimension

    // Initialize matrices (using simple values for demonstration)
    std::vector<float> h_A(M * K, 1.0f);
    std::vector<float> h_B(K * N, 2.0f);
    std::vector<float> h_C(M * N, 0.0f);

    std::cout << "Running RAJA Matrix Multiplication (" << M << "x" << K << " * " << K << "x" << N << ")..." << std::endl;

    run_raja_matmul(h_A, h_B, h_C, M, N, K);

    std::cout << "Matrix multiplication complete. Result at (0, 0): " << h_C[0] << std::endl;
    return 0;
}
```

