## Example 2: Matrix Multiplication (Tiled/Blocked Operation)

Matrix multiplication is more complex because it requires managing 2D indexing and often benefits from tiling/blocking, which RAJA can help structure.

### 1. Original CUDA Code (Simplified)

We will use a simple, non-tiled implementation for direct comparison.

```c++
// cuda_matmul.cu
#include <cuda_runtime.h>
#include <iostream>

// CUDA Kernel for C = A * B
__global__ void matmulKernel(const float* A, const float* B, float* C, int M, int N, int K) {
    // Calculate the global row (row_idx) and column (col_idx) for C
    int row_idx = blockIdx.y * blockDim.y + threadIdx.y;
    int col_idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (row_idx < M && col_idx < N) {
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            // A is M x K, B is K x N
            sum += A[row_idx * K + k] * B[k * N + col_idx];
        }
        C[row_idx * N + col_idx] = sum;
    }
}

// ... (Host code for memory management and launch configuration omitted for brevity)
```

### 2. RAJA Conversion

RAJA allows us to use nested `parallel_for` loops to map the outer loops (rows and columns) and then use the inner loop structure to represent the dot product summation.

```c++
// raja_matmul.cpp
#include <iostream>
#include <vector>
#include <raja/raja.hpp>

using namespace raja;

void run_raja_matmul(
    const std::vector<float>& h_A, 
    const std::vector<float>& h_B, 
    std::vector<float>& h_C, 
    int M, int N, int K) 
{
    auto policy = default_policy<cuda_backend>(); 

    // Outer loops: Iterate over rows (M) and columns (N) of the result matrix C
    parallel_for(policy, range(0, M), [&](int row_idx) {
        parallel_for(policy, range(0, N), [&](int col_idx) {

            // Inner loop: Calculate the dot product (summation over K)
            float sum = 0.0f;
            for (int k = 0; k < K; ++k) {
                // Accessing data using the loop indices
                sum += h_A[row_idx * K + k] * h_B[k * N + col_idx];
            }

            // Store the result
            h_C[row_idx * N + col_idx] = sum;
        });
    });
}

int main() {
    // Define matrix dimensions
    const int M = 128; // Rows of A, Rows of C
    const int N = 128; // Cols of B, Cols of C
    const int K = 128; // Inner dimension

    // Initialize matrices (using simple initialization for demonstration)
    std::vector<float> h_A(M * K, 1.0f / K);
    std::vector<float> h_B(K * N, 1.0f / K);
    std::vector<float> h_C(M * N, 0.0f);

    std::cout << "Running RAJA Matrix Multiplication (" << M << "x" << K << " * " << K << "x" << N << ")..." << std::endl;

    // In a production RAJA code, the vectors would be RAJA::device_vector 
    // to ensure the data resides on the GPU throughout the computation.
    run_raja_matmul(h_A, h_B, h_C, M, N, K);

    std::cout << "Matrix multiplication complete. Result C[0][0]: " << h_C[0] << std::endl;
    return 0;
}
```

