const int N = 128; // Columns of B and C
const int K = 128; // Inner dimension

void run_raja_matmul(std::vector<float>& h_A, std::vector<float>& h_B, std::vector<float>& h_C) {

    // Initialize C to zero (necessary for accumulation)
    std::fill(h_C.begin(), h_C.end(), 0.0f);

    // RAJA handles the mapping of the outer loops (M and N) to the grid/blocks.
    // The inner loop (K) remains sequential within each thread.

    // Outer loop: Iterate over rows of C (M)
    parallel_for(0, M, [&](int row_m) {
        // Middle loop: Iterate over columns of C (N)
        parallel_for(0, N, [&](int col_n) {
            float sum = 0.0f;
            // Inner loop: The reduction/accumulation loop (K)
            for (int k = 0; k < K; ++k) {
                // Accessing data using 1D indexing, matching the CUDA layout
                sum += h_A[row_m * K + k] * h_B[k * N + col_n];
            }
            // Store the result
            h_C[row_m * N + col_n] = sum;
        });
    });
}

int main() {
    // Setup data (M x K) for A, (K x N) for B, (M x N) for C
    std::vector<float> h_A(M * K);
    std::vector<float> h_B(K * N);
    std::vector<float> h_C(M * N);

    // Initialize data (e.g., to 1.0)
    std::fill(h_A.begin(), h_A.end(), 1.0f);
    std::fill(h_B.begin(), h_B.end(), 1.0f);

    std::cout << "Running RAJA Matrix Multiplication (M=" << M << ", N=" << N << ", K=" << K << ")..." << std::endl;

    // *** Execution ***
    // Again, this requires RAJA to be built with the CUDA backend enabled.
    run_raja_matmul(h_A, h_B, h_C);

    // Expected result for all 1s: C[i][j] = K (128)
    std::cout << "RAJA execution complete. Result C[0][0]: " << h_C[0] << std::endl;

    return 0;
}
