                      const std::vector<float>& h_B, 
                      std::vector<float>& h_C, 
                      int M, int N, int K) {

    // RAJA requires the data to be accessible by the parallel region.
    // For simplicity, we assume the host vectors are used, and RAJA 
    // handles the necessary device transfers based on the policy.

    // Outer loop: Iterate over rows of C (M)
    raja::parallel_for(
        raja::range(0, M), 
        policy(), 
        [&](int row_idx) {

            // Inner loop: Iterate over columns of C (N)
            raja::parallel_for(
                raja::range(0, N), 
                policy(), 
                [&](int col_idx) {

                    float sum = 0.0f;
                    // Innermost loop: The dot product (K)
                    for (int k = 0; k < K; ++k) {
                        // Accessing data using 1D indexing, matching the CUDA layout
                        sum += h_A[row_idx * K + k] * h_B[k * N + col_idx];
                    }
                    // Writing the result
                    h_C[row_idx * N + col_idx] = sum;
                }
            );
        }
    );
}

int main() {
    // Define matrix dimensions
    const int M = 16; // Rows of A and C
    const int N = 16; // Columns of B and C
    const int K = 16; // Inner dimension

    // Initialize matrices (e.g., with 1.0 for easy verification)
    std::vector<float> h_A(M * K, 1.0f);
    std::vector<float> h_B(K * N, 1.0f);
    std::vector<float> h_C(M * N, 0.0f);

    std::cout << "Running RAJA Matrix Multiplication (" << M << "x" << K << " * " << K << "x" << N << ")..." << std::endl;

    // Execute the RAJA parallel computation
    run_raja_matmul(h_A, h_B, h_C, M, N, K);

    // Verification: Since A and B are all 1s, the result C[i][j] should be K (16.0)
    std::cout << "Verification: C[0][0] = " << h_C[0] << " (Expected: " << K << ")" << std::endl;

    return 0;
}
