### RAJA version

```cpp
// vecadd_raja.cu
#include <RAJA/RAJA.hpp>
#include <cstdio>
#include <cstdlib>

int main()
{
    const int N = 1 << 20;          // 1M elements
    const int threadsPerBlock = 256;
    const int blocks = (N + threadsPerBlock - 1) / threadsPerBlock;

    // Allocate host memory
    float *h_a = new float[N];
    float *h_b = new float[N];
    float *h_c = new float[N];

    for (int i = 0; i < N; ++i) { h_a[i] = i; h_b[i] = 2*i; }

    // Allocate device memory
    float *d_a, *d_b, *d_c;
    RAJA::cuda_malloc(&d_a, N*sizeof(float));
    RAJA::cuda_malloc(&d_b, N*sizeof(float));
    RAJA::cuda_malloc(&d_c, N*sizeof(float));

    // Copy data to device
    RAJA::cuda_memcpy(d_a, h_a, N*sizeof(float), RAJA::cudaMemcpyHostToDevice);
    RAJA::cuda_memcpy(d_b, h_b, N*sizeof(float), RAJA::cudaMemcpyHostToDevice);

    // RAJA loop: 1‑D range [0,N)
    RAJA::forall<RAJA::cuda_exec<threadsPerBlock>>(
        RAJA::RangeSegment(0, N),
        [=] __device__ (int i) {
            d_c[i] = d_a[i] + d_b[i];
        });

    // Wait for GPU to finish
    RAJA::cuda_device_sync();

    // Copy result back
    RAJA::cuda_memcpy(h_c, d_c, N*sizeof(float), RAJA::cudaMemcpyDeviceToHost);

    // sanity check
    for (int i = 0; i < 10; ++i)
        printf("%f + %f = %f\n", h_a[i], h_b[i], h_c[i]);

    // Clean up
    RAJA::cuda_free(d_a);
    RAJA::cuda_free(d_b);
    RAJA::cuda_free(d_c);
    delete[] h_a; delete[] h_b; delete[] h_c;
    return 0;
}
```

