**Example 1: Simple Matrix Multiplication**

CUDA Kernel:
```c
__global__ void matmul_kernel(float *A, float *B, float *C, int M, int N, int P) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int idy = blockIdx.y * blockDim.y + threadIdx.y;
    int idz = blockIdx.z * blockDim.z + threadIdx.z;

    if (idx < M && idy < N && idz < P) {
        float sum = 0.0f;
        for (int i = 0; i < M; i++) {
            sum += A[idx * M + i] * B[i * N + idy];
        }
        C[idx * N + idy] = sum;
    }
}
```

RAJA Version:
```c
#include <raja/RAJA/config.hpp>
#include <raja/util/Types.hpp>
#include <raja/patterns/For.hpp>
#include <raja/patterns/Tiled.hpp>

int main() {
    // Define the matrix dimensions
    int M = 10;
    int N = 10;
    int P = 10;

    // Allocate memory for the matrices
    float *A = new float[M * N];
    float *B = new float[N * P];
    float *C = new float[M * P];

    // Initialize the matrices
    for (int i = 0; i < M * N; i++) {
        A[i] = i;
    }
    for (int i = 0; i < N * P; i++) {
        B[i] = i;
    }

    // Define the RAJA kernel
    RAJA::forall<RAJA::omp_parallel_for_exec>(RAJA::RangeSegment(0, M), RAJA::RangeSegment(0, N), RAJA::RangeSegment(0, P)) {
        float sum = 0.0f;
        RAJA::forall<RAJA::omp_parallel_for_exec>(RAJA::RangeSegment(0, M)) {
            sum += A[RAJA::index<0>() * M + RAJA::index<1>()] * B[RAJA::index<1>() * N + RAJA::index<2>()];
        }
        C[RAJA::index<0>() * N + RAJA::index<1>()] = sum;
    }

    // Print the result
    for (int i = 0; i < M * P; i++) {
        std::cout << C[i] << " ";
    }
    std::cout << std::endl;

    // Clean up
    delete[] A;
    delete[] B;
    delete[] C;

    return 0;
}
```

