#include <iostream>

// CUDA Kernel for C = A * B
__global__ void matmulKernel(const float* A, const float* B, float* C, int M, int N, int K) {
    // Calculate the global row (row_idx) and column (col_idx) for C
    int row_idx = blockIdx.y * blockDim.y + threadIdx.y;
    int col_idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (row_idx < M && col_idx < N) {
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            // A is M x K, B is K x N
            sum += A[row_idx * K + k] * B[k * N + col_idx];
        }
        C[row_idx * N + col_idx] = sum;
    }
}

// ... (Host code for memory management and launch configuration omitted for brevity)
