## Example 1: Simple Vector Addition (Element-wise Operation)

This is the most straightforward conversion, demonstrating how a simple parallel loop maps directly.

### 1. Original CUDA Code

```c++
// cuda_vector_add.cu
#include <cuda_runtime.h>
#include <iostream>

// CUDA Kernel
__global__ void vectorAddKernel(const float* A, const float* B, float* C, int N) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < N) {
        C[i] = A[i] + B[i];
    }
}

void run_cuda_vector_add(const float* h_A, const float* h_B, float* h_C, int N) {
    // 1. Allocate device memory
    float *d_A, *d_B, *d_C;
    cudaMalloc((void**)&d_A, N * sizeof(float));
    cudaMalloc((void**)&d_B, N * sizeof(float));
    cudaMalloc((void**)&d_C, N * sizeof(float));

    // 2. Copy host to device
    cudaMemcpy(d_A, h_A, N * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_B, h_B, N * sizeof(float), cudaMemcpyHostToDevice);

    // 3. Kernel Launch Configuration
    int threadsPerBlock = 256;
    int blocksPerGrid = (N + threadsPerBlock - 1) / threadsPerBlock;

    // 4. Launch Kernel
    vectorAddKernel<<<blocksPerGrid, threadsPerBlock>>>(d_A, d_B, d_C, N);

    // 5. Copy device to host
    cudaMemcpy(h_C, d_C, N * sizeof(float), cudaMemcpyDeviceToHost);

    // 6. Cleanup
    cudaFree(d_A);
    cudaFree(d_B);
    cudaFree(d_C);
}
```

### 2. RAJA Conversion

In RAJA, we use `raja::parallel_for` and RAJA's memory management abstractions (often implicitly handled by the backend setup).

```c++
// raja_vector_add.cpp
#include <iostream>
#include <vector>
#include <raja/raja.hpp>

// Define the RAJA execution policy (must be configured for CUDA)
// In a real setup, this policy would be set up via RAJA configuration files.
// For this example, we assume the CUDA backend is active.
using policy = raja::cuda::policy; 

void run_raja_vector_add(const std::vector<float>& h_A, 
                         const std::vector<float>& h_B, 
                         std::vector<float>& h_C, 
                         int N) {

    // RAJA handles the device memory allocation and transfer implicitly 
    // when using the policy and appropriate RAJA types/functions.

    // We use RAJA's parallel_for to abstract the kernel launch.
    raja::parallel_for(
        raja::range(0, N), // The iteration space (like the loop bounds)
        policy(),          // The execution policy (specifies CUDA backend)
        [&](int i) {
            // This lambda body is the equivalent of the kernel body.
            // RAJA ensures that 'i' is executed on a device thread/block 
            // if the policy is CUDA.
            h_C[i] = h_A[i] + h_B[i];
        }
    );

    // Note: In a full RAJA application, you would use RAJA's memory 
    // management functions (e.g., raja::device_vector) to manage 
    // the host/device transfers explicitly if the data wasn't already 
    // managed by the host vector.
}

int main() {
    const int N = 1024 * 1024;
    std::vector<float> h_A(N, 1.0f);
    std::vector<float> h_B(N, 2.0f);
    std::vector<float> h_C(N);

    std::cout << "Running RAJA Vector Addition..." << std::endl;

    // The RAJA call handles the entire device execution pipeline
    run_raja_vector_add(h_A, h_B, h_C, N);

    std::cout << "First element result: " << h_C[0] << std::endl; // Should be 3.0
    std::cout << "Last element result: " << h_C[N-1] << std::endl; // Should be 3.0

    return 0;
}
```

