## Example 2: Matrix Multiplication (Tiled/Blocked Operation)

Matrix multiplication is more complex because it requires managing 2D indexing and often benefits from tiling, which RAJA handles more abstractly than raw CUDA thread indexing.

### 1. Original CUDA Code (Simplified)

We will use a simplified, non-tiled CUDA implementation for brevity, focusing on the parallel structure.

```c++
// cuda_matmul.cu
// ... (Includes and setup omitted for brevity)

__global__ void matmulKernel(const float* A, const float* B, float* C, int M, int N, int K) {
    // Calculate the global row (row_idx) and column (col_idx) for the output C[row_idx][col_idx]
    int row_idx = blockIdx.y * blockDim.y + threadIdx.y;
    int col_idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (row_idx < M && col_idx < N) {
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            // C[row_idx][col_idx] += A[row_idx][k] * B[k][col_idx]
            sum += A[row_idx * K + k] * B[k * N + col_idx];
        }
        C[row_idx * N + col_idx] = sum;
    }
}
// ... (Host code for launching and memory management omitted)
```

### 2. RAJA Conversion

RAJA allows us to iterate over the dimensions ($M$ and $N$) using nested `parallel_for` loops, letting RAJA manage the mapping of these loops onto the underlying hardware grid/blocks.

```c++
// raja_matmul.cpp
#include <iostream>
#include <vector>
#include <raja/raja.hpp>

using policy = raja::cuda::policy; 

void run_raja_matmul(const std::vector<float>& h_A, 
                      const std::vector<float>& h_B, 
                      std::vector<float>& h_C, 
                      int M, int N, int K) {

    // RAJA requires the data to be accessible by the parallel region.
    // For simplicity, we assume the host vectors are used, and RAJA 
    // handles the necessary device transfers based on the policy.

    // Outer loop: Iterate over rows of C (M)
    raja::parallel_for(
        raja::range(0, M), 
        policy(), 
        [&](int row_idx) {

            // Inner loop: Iterate over columns of C (N)
            raja::parallel_for(
                raja::range(0, N), 
                policy(), 
                [&](int col_idx) {

                    float sum = 0.0f;
                    // Innermost loop: The dot product (K)
                    for (int k = 0; k < K; ++k) {
                        // Accessing data using 1D indexing, matching the CUDA layout
                        sum += h_A[row_idx * K + k] * h_B[k * N + col_idx];
                    }
                    // Writing the result
                    h_C[row_idx * N + col_idx] = sum;
                }
            );
        }
    );
}

int main() {
    // Define matrix dimensions
    const int M = 16; // Rows of A and C
    const int N = 16; // Columns of B and C
    const int K = 16; // Inner dimension

    // Initialize matrices (e.g., with 1.0 for easy verification)
    std::vector<float> h_A(M * K, 1.0f);
    std::vector<float> h_B(K * N, 1.0f);
    std::vector<float> h_C(M * N, 0.0f);

    std::cout << "Running RAJA Matrix Multiplication (" << M << "x" << K << " * " << K << "x" << N << ")..." << std::endl;

    // Execute the RAJA parallel computation
    run_raja_matmul(h_A, h_B, h_C, M, N, K);

    // Verification: Since A and B are all 1s, the result C[i][j] should be K (16.0)
    std::cout << "Verification: C[0][0] = " << h_C[0] << " (Expected: " << K << ")" << std::endl;

    return 0;
}
```

