## 2. 2‑D 5‑Point Laplacian Stencil

This example demonstrates a more realistic, multi‑dimensional kernel.  
The CUDA version uses a 2‑D grid of thread blocks; the RAJA version uses `RAJA::kernel` with a 2‑D policy.

### CUDA version

```cpp
// stencil.cu
#include <cuda_runtime.h>
#include <cstdio>

__global__ void laplacian_kernel(const float *in, float *out,
                                 int nx, int ny)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x; // x‑index
    int j = blockIdx.y * blockDim.y + threadIdx.y; // y‑index

    if (i > 0 && i < nx-1 && j > 0 && j < ny-1) {
        int idx = j*nx + i;
        out[idx] = 4.0f*in[idx]
                 - in[idx-1] - in[idx+1]
                 - in[idx-nx] - in[idx+nx];
    }
}

int main()
{
    const int nx = 512, ny = 512;
    const int N = nx*ny;
    const dim3 threadsPerBlock(16, 16);
    const dim3 numBlocks((nx + threadsPerBlock.x - 1)/threadsPerBlock.x,
                         (ny + threadsPerBlock.y - 1)/threadsPerBlock.y);

    float *h_in  = new float[N];
    float *h_out = new float[N];
    for (int j = 0; j < ny; ++j)
        for (int i = 0; i < nx; ++i)
            h_in[j*nx + i] = 1.0f;   // arbitrary init

    float *d_in, *d_out;
    cudaMalloc(&d_in,  N*sizeof(float));
    cudaMalloc(&d_out, N*sizeof(float));

    cudaMemcpy(d_in, h_in, N*sizeof(float), cudaMemcpyHostToDevice);

    laplacian_kernel<<<numBlocks, threadsPerBlock>>>(d_in, d_out, nx, ny);
    cudaDeviceSynchronize();

    cudaMemcpy(h_out, d_out, N*sizeof(float), cudaMemcpyDeviceToHost);

    printf("center value = %f\n", h_out[(ny/2)*nx + nx/2]);

    cudaFree(d_in); cudaFree(d_out);
    delete[] h_in; delete[] h_out;
    return 0;
}
```

