    // sanity check
    for (int i = 0; i < 10; ++i)
        printf("%f + %f = %f\n", h_a[i], h_b[i], h_c[i]);

    // Clean up
    RAJA::cuda_free(d_a);
    RAJA::cuda_free(d_b);
    RAJA::cuda_free(d_c);
    delete[] h_a; delete[] h_b; delete[] h_c;
    return 0;
}
