    // (like CMake) that links RAJA against the CUDA backend. 
    // The RAJA framework handles the translation of parallel_for into the 
    // appropriate CUDA kernel launch internally.

    run_raja_vector_add(h_A, h_B, h_C, N);

    std::cout << "RAJA execution complete. Result at index 0: " << h_C[0] << std::endl;

