## Example 2: Matrix Multiplication (Tiled/Blocked Operation)

Matrix multiplication is more complex because it requires managing 2D indexing and often benefits from tiling/blocking, which RAJA handles more abstractly than raw CUDA thread indexing.

### 1. Original CUDA Code (Simplified)

We will use a simple, non-tiled implementation for direct comparison.

```c++
// cuda_matmul.cu
#include <cuda_runtime.h>
#include <iostream>

// Kernel for C = A * B (C[i][j] = sum(A[i][k] * B[k][j]))
__global__ void matmulKernel(const float* A, const float* B, float* C, int M, int N, int K) {
    // Calculate the row (i) and column (j) of the output matrix C
    int i = blockIdx.y * blockDim.y + threadIdx.y; // Row index
    int j = blockIdx.x * blockDim.x + threadIdx.x; // Column index

    if (i < M && j < N) {
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            // A is M x K, B is K x N
            sum += A[i * K + k] * B[k * N + j];
        }
        C[i * N + j] = sum;
    }
}

// ... (Host code for allocation and launch omitted for brevity)
```

### 2. RAJA Conversion

RAJA allows us to express the iteration space over the dimensions $(M, N)$ and then use a nested loop structure, letting RAJA manage the parallelization across the outer dimensions.

```c++
// raja_matmul.cpp
#include <iostream>
#include <vector>
#include <raja/raja.hpp>

using policy = raja::cuda::policy; 

void run_raja_matmul(const std::vector<float>& h_A, 
                     const std::vector<float>& h_B, 
                     std::vector<float>& h_C, 
                     int M, int N, int K) {

    // RAJA's parallel_for is excellent for outer loops. 
    // For inner loops (like the 'k' summation), we often rely on 
    // the compiler/backend to vectorize or use RAJA's reduction/inner loop constructs.

    // We parallelize over the output matrix C (M rows, N columns)
    raja::parallel_for(
        raja::range(0, M), // Iterate over rows (i)
        policy(),
        [&](int i) {
            // For each row i, we parallelize over the columns (j)
            raja::parallel_for(
                raja::range(0, N), // Iterate over columns (j)
                policy(),
                [&](int j) {
                    float sum = 0.0f;
                    // The inner loop (k) is sequential in this RAJA structure, 
                    // but the outer loops (i, j) are parallelized across the device.
                    for (int k = 0; k < K; ++k) {
                        // Accessing data using 1D indexing consistent with the original
                        sum += h_A[i * K + k] * h_B[k * N + j];
                    }
                    // Writing the result back to the host vector (RAJA handles synchronization)
                    h_C[i * N + j] = sum;
                }
            );
        }
    );
}

int main() {
    // Define matrix dimensions
    const int M = 1024; // Rows of A, Rows of C
    const int N = 1024; // Cols of B, Cols of C
    const int K = 1024; // Inner dimension

    // Initialize matrices (using simple values for testing)
    std::vector<float> h_A(M * K, 1.0f);
    std::vector<float> h_B(K * N, 2.0f);
    std::vector<float> h_C(M * N, 0.0f);

    std::cout << "Running RAJA Matrix Multiplication (M=" << M << ", N=" << N << ", K=" << K << ")..." << std::endl;

    run_raja_matmul(h_A, h_B, h_C, M, N, K);

    std::cout << "Matrix multiplication complete. Result at (0, 0): " << h_C[0] << std::endl;
    return 0;
}
```

