### RAJA version

```cpp
// stencil_raja.cu
#include <RAJA/RAJA.hpp>
#include <cstdio>
#include <cstdlib>

int main()
{
    const int nx = 512, ny = 512;
    const int N  = nx*ny;

    // Host data
    float *h_in  = new float[N];
    float *h_out = new float[N];
    for (int j = 0; j < ny; ++j)
        for (int i = 0; i < nx; ++i)
            h_in[j*nx + i] = 1.0f;   // arbitrary init

    // Device data
    float *d_in, *d_out;
    RAJA::cuda_malloc(&d_in,  N*sizeof(float));
    RAJA::cuda_malloc(&d_out, N*sizeof(float));

    RAJA::cuda_memcpy(d_in, h_in, N*sizeof(float), RAJA::cudaMemcpyHostToDevice);

    // 2‑D layout: row‑major (C order)
    using Layout = RAJA::Layout<2>;
    Layout layout{nx, ny};

    // RAJA kernel: 2‑D range [0,nx) × [0,ny)
    RAJA::kernel<RAJA::cuda_exec<16, 16>>(
        RAJA::make_tuple(RAJA::RangeSegment(0, nx),
                         RAJA::RangeSegment(0, ny)),
        [=] __device__ (int i, int j) {
            if (i > 0 && i < nx-1 && j > 0 && j < ny-1) {
                int idx = j*nx + i;
                d_out[idx] = 4.0f*d_in[idx]
                           - d_in[idx-1] - d_in[idx+1]
                           - d_in[idx-nx] - d_in[idx+nx];
            }
        });

    RAJA::cuda_device_sync();

    RAJA::cuda_memcpy(h_out, d_out, N*sizeof(float), RAJA::cudaMemcpyDeviceToHost);

    printf("center value = %f\n", h_out[(ny/2)*nx + nx/2]);

    RAJA::cuda_free(d_in);
    RAJA::cuda_free(d_out);
    delete[] h_in; delete[] h_out;
    return 0;
}
```

